select sum(count) from( select count(*) count from MST_CUSTOMER_INFO T1 ,MST_COUNTER_PARTY T2 where T1.CUSTOMER_ID=T2.LINK_ID and (T1.CUSTOMER_ID in
null) or T1.CUSTOMER_ID in (
#{item.customerId,jdbcType=VARCHAR}
) union all select count(*) count from MST_CUSTOMER_INFO T3 ,FIN_PRODUCT T4 where T3.CUSTOMER_ID=T4.ISSUER and T3.CUSTOMER_ID in
#{item.customerId,jdbcType=VARCHAR}
)

SELECT T1.PERSON_ID code, T1.PERSON_ID name, T2.CUSTOMER_NAME shortName, T1.PERSON_ID hidCode FROM MST_CUSTOMER_INFO_ADD T1,MST_CUSTOMER_INFO T2
T1.CUSTOMER_ID=T2.CUSTOMER_ID AND T2.CUSTOMER_TYPE=#{naturalperson}
AND T1.PERSON_ID like concat(#{param},'%')

select count(*) from MST_CUSTOMER_INFO T1 left join
MST_CUSTOMER_INFO_ADD T2 ON T1.CUSTOMER_ID=T2.CUSTOMER_ID
where
T2.PERSON_ID=#{personId}
and T2.CUSTOMER_ID != #{customerId}
